PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS student_profiles (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), admission_number TEXT NOT NULL, index_number TEXT, first_name TEXT NOT NULL, middle_name TEXT, surname TEXT NOT NULL, preferred_name TEXT, gender TEXT, date_of_birth TEXT, place_of_birth TEXT, nationality TEXT, photograph_path TEXT, qr_code TEXT NOT NULL UNIQUE, class_id TEXT REFERENCES classes(id), stream_id TEXT REFERENCES streams(id), house_id TEXT REFERENCES houses(id), admission_date TEXT, previous_school TEXT, admission_type TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, admission_number));
CREATE TABLE IF NOT EXISTS student_family_contacts (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student_profiles(id), contact_type TEXT NOT NULL, full_name TEXT NOT NULL, relationship TEXT, telephone TEXT, alternative_phone TEXT, address TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS student_health_records (student_id TEXT PRIMARY KEY REFERENCES student_profiles(id), allergies TEXT, conditions TEXT, medications TEXT, blood_group TEXT, emergency_notes TEXT, restricted_notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS student_documents (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student_profiles(id), document_type TEXT NOT NULL, storage_key TEXT NOT NULL, uploaded_by TEXT REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS student_class_history (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student_profiles(id), class_id TEXT REFERENCES classes(id), stream_id TEXT REFERENCES streams(id), academic_year_id TEXT REFERENCES academic_years(id), reason TEXT NOT NULL, effective_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parent_student_links (parent_user_id TEXT NOT NULL REFERENCES users(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), relationship TEXT, telephone TEXT, created_at TEXT NOT NULL, PRIMARY KEY(parent_user_id, student_id));
CREATE TABLE IF NOT EXISTS admission_applications (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), application_number TEXT NOT NULL UNIQUE, stage TEXT NOT NULL, applicant_data TEXT NOT NULL, admission_letter_key TEXT, enrollment_confirmation_key TEXT, student_id TEXT REFERENCES student_profiles(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_student_profile_school_class ON student_profiles(school_id, class_id);
CREATE INDEX IF NOT EXISTS idx_student_family_phone ON student_family_contacts(telephone);
CREATE INDEX IF NOT EXISTS idx_admission_stage ON admission_applications(school_id, stage);
